OUT = os.path.join(ROOT, 'premade-cards', '12th', 'Chemistry', 'class12-chemistry-ch04-d-and-f-block-elements')
d = Deck('Chapter 4: The d- and f-Block Elements', 'Class 12', ['class-12', 'chemistry', 'ch-4'])
d.description = 'Transition metal trends, oxidation states, E° values, magnetism, colour, catalysis, K₂Cr₂O₇, KMnO₄, lanthanoids and actinoids'
